function validate([targetGrid]) {
  if (!Array.isArray(targetGrid) || targetGrid.length < 1 || targetGrid.length > 60) return 'targetGrid needs 1 to 60 rows.';
  const cols = Array.isArray(targetGrid[0]) ? targetGrid[0].length : 0;
  if (cols < 1 || cols > 60) return 'Each row needs 1 to 60 cells.';
  for (const row of targetGrid) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 60)) return 'Each color is an integer from 1 to 60.';
  }
  return null;
}

