function isPrintable(targetGrid) {
  const rows = targetGrid.length;
  const cols = targetGrid[0].length;
  const top = new Array(61).fill(rows);
  const left = new Array(61).fill(cols);
  const bottom = new Array(61).fill(-1);
  const right = new Array(61).fill(-1);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const color = targetGrid[r][c];
      top[color] = Math.min(top[color], r);
      left[color] = Math.min(left[color], c);
      bottom[color] = Math.max(bottom[color], r);
      right[color] = Math.max(right[color], c);
    }
  }

  const covers = Array.from({ length: 61 }, () => new Set());
  const indegree = new Array(61).fill(0);
  for (let color = 1; color <= 60; color++) {
    for (let r = top[color]; r <= bottom[color]; r++) {
      for (let c = left[color]; c <= right[color]; c++) {
        const other = targetGrid[r][c];
        if (other !== color && !covers[color].has(other)) {
          covers[color].add(other);
          indegree[other]++;
        }
      }
    }
  }

  const queue = [];
  let used = 0;
  for (let color = 1; color <= 60; color++) {
    if (bottom[color] < 0) continue;
    used++;
    if (indegree[color] === 0) queue.push(color);
  }
  let head = 0;
  while (head < queue.length) {
    const color = queue[head];
    head++;
    for (const next of covers[color]) {
      indegree[next]--;
      if (indegree[next] === 0) queue.push(next);
    }
  }
  return queue.length === used;
}

