  // Undo the printing: repeatedly remove a color whose rectangle shows only itself or removed cells.
  const grid = targetGrid.map(row => row.slice());
  const boxes = new Map();
  grid.forEach((row, r) => row.forEach((color, c) => {
    if (!boxes.has(color)) boxes.set(color, { r1: r, c1: c, r2: r, c2: c });
    const b = boxes.get(color);
    b.r1 = Math.min(b.r1, r); b.c1 = Math.min(b.c1, c); b.r2 = Math.max(b.r2, r); b.c2 = Math.max(b.c2, c);
  }));
  let remaining = [...boxes.keys()];
  while (remaining.length) {
    const peel = remaining.find(color => {
      const b = boxes.get(color);
      for (let r = b.r1; r <= b.r2; r++) for (let c = b.c1; c <= b.c2; c++) if (grid[r][c] !== color && grid[r][c] !== 0) return false;
