function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 40 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 4);
  const cols = large ? 40 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 4);
  const palette = large ? 60 : 1 + Math.floor(rand() * 6);
  const pick = (limit) => Math.floor(rand() * limit);
  const mode = rand();
  if (mode < 0.2) {
    // Random colors: usually not printable.
    return [Array.from({ length: rows }, () => Array.from({ length: cols }, () => 1 + pick(palette)))];
  }
  // Simulate a real printing order with distinct colors, the first covering everything.
  const colors = Array.from({ length: palette }, (_, i) => i + 1);
  for (let i = colors.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [colors[i], colors[j]] = [colors[j], colors[i]];
  }
  const grid = Array.from({ length: rows }, () => new Array(cols).fill(colors[0]));
  for (const color of colors.slice(1)) {
    const r1 = pick(rows), r2 = r1 + pick(rows - r1), c1 = pick(cols), c2 = c1 + pick(cols - c1);
    for (let r = r1; r <= r2; r++) for (let c = c1; c <= c2; c++) grid[r][c] = color;
  }
  if (mode < 0.6) {
    // Change a cell or two, which often makes the grid impossible.
    const changes = 1 + pick(2);
    for (let k = 0; k < changes; k++) grid[pick(rows)][pick(cols)] = 1 + pick(palette);
  }
  return [grid];
}
